--liquibase formatted sql

--changeset lossrun:0009-ledger-digest splitStatements:false
--comment: Database digests generated by audit-proof (sp_generate_database_ledger_digest), kept as append-only ledger rows. In Azure, automatic digest storage also uploads one every 30 s to immutable Blob (Terraform: infra/sql.tf ledgerDigestUploads); the container copy is the trust anchor, this table is the local record.
IF OBJECT_ID(N'dbo.LedgerDigest', N'U') IS NULL
CREATE TABLE dbo.LedgerDigest
(
    Id           bigint IDENTITY(1, 1) NOT NULL CONSTRAINT PK_LedgerDigest PRIMARY KEY,
    BlockId      bigint         NOT NULL,
    DigestJson   nvarchar(4000) NOT NULL,
    GeneratedUtc datetime2(3)   NOT NULL,
    Source       nvarchar(32)   NOT NULL
)
WITH (LEDGER = ON (APPEND_ONLY = ON));
--rollback DROP TABLE IF EXISTS dbo.LedgerDigest;

--changeset lossrun:0009-app-user runOnChange:true splitStatements:false
--comment: Database user for the Function App's managed identity (Entra), read/write without DDL. Azure SQL only (EngineEdition 5); a no-op on SQL Server containers or when the appPrincipalName changelog parameter is empty.
DECLARE @principal sysname = N'${appPrincipalName}';
IF @principal <> N'' AND CAST(SERVERPROPERTY('EngineEdition') AS int) = 5
BEGIN
    DECLARE @name nvarchar(300) = QUOTENAME(@principal);
    DECLARE @sql nvarchar(max) =
        CASE WHEN DATABASE_PRINCIPAL_ID(@principal) IS NULL THEN N'CREATE USER ' + @name + N' FROM EXTERNAL PROVIDER; ' ELSE N'' END
        + N'ALTER ROLE db_datareader ADD MEMBER ' + @name + N'; ALTER ROLE db_datawriter ADD MEMBER ' + @name + N'; GRANT EXECUTE TO ' + @name + N';';
    EXEC sys.sp_executesql @sql;
END
--rollback DECLARE @principal sysname = N'${appPrincipalName}'; DECLARE @sql nvarchar(max) = N'DROP USER ' + QUOTENAME(@principal) + N';'; IF @principal <> N'' AND DATABASE_PRINCIPAL_ID(@principal) IS NOT NULL EXEC sys.sp_executesql @sql;
